"""Worlds whose law is generated by a known machine with a memory of names.

Each generator returns, for every episode, the text and, for every position, the
machine's state and the set of names its future still depends on, *before* the sign at
that position is read.  The learner never sees these; they are used only to check
whether what it built is the same machine.  Names are drawn afresh from a pool so
large that no name is likely to occur in two episodes.  END marks the end of a text.
"""
import random

END = -1
POOL = 10 ** 9


def _fresh(rng, used):
    while True:
        a = 1000 + rng.randrange(POOL)
        if a not in used:
            used.add(a)
            return a


def bind_recall(n, seed, pairs=2):
    """k1 v1 k2 v2 Q, then the keys in a random order, each followed by its value.
    In the question phase the memory is a set of pairs: their order does not matter."""
    rng = random.Random(seed)
    Q = 0
    out = []
    for _ in range(n):
        used, text, truth = set(), [], []
        ks, vs = [], []
        for i in range(pairs):
            truth.append((("bind-key", i), set(ks) | set(vs)))
            ks.append(_fresh(rng, used))
            text.append(ks[-1])
            truth.append((("bind-value", i), set(ks) | set(vs)))
            vs.append(_fresh(rng, used))
            text.append(vs[-1])
        truth.append((("mark",), set(ks) | set(vs)))
        text.append(Q)
        left = list(range(pairs))
        rng.shuffle(left)
        while left:
            live = {ks[i] for i in left} | {vs[i] for i in left}
            truth.append((("ask-key", len(left)), live))
            i = left.pop(0)
            text.append(ks[i])
            truth.append((("ask-value", len(left) + 1), (live - {ks[i]})))
            text.append(vs[i])
        truth.append((("end",), set()))
        text.append(END)
        out.append((text, truth))
    return out


def stack(n, seed, depth=3):
    """Names are opened and must be closed in reverse order.  The memory is a stack."""
    rng = random.Random(seed)
    out = []
    for _ in range(n):
        used, text, truth, st = set(), [], [], []
        while True:
            truth.append((("depth", len(st)), set(st)))
            if not st:
                if rng.random() < 0.3:
                    text.append(END)
                    break
                st.append(_fresh(rng, used))
                text.append(st[-1])
            elif len(st) < depth and rng.random() < 0.4:
                st.append(_fresh(rng, used))
                text.append(st[-1])
            else:
                text.append(st.pop())
        out.append((text, truth))
    return out


def overwrite(n, seed):
    """A name is set.  A later name replaces it.  G asks for the current one."""
    rng = random.Random(seed)
    G = 0
    out = []
    for _ in range(n):
        used, text, truth = set(), [], []
        truth.append((("empty",), set()))
        cur = _fresh(rng, used)
        text.append(cur)
        while True:
            truth.append((("holding",), {cur}))
            u = rng.random()
            if u < 0.35:
                cur = _fresh(rng, used)
                text.append(cur)
            elif u < 0.75:
                text.append(G)
                truth.append((("asked",), {cur}))
                text.append(cur)
            else:
                text.append(END)
                break
        out.append((text, truth))
    return out


WORLDS = {"bind and recall": bind_recall, "stack": stack, "overwrite": overwrite}
